//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//	NAME:			Alternation                                                                                                                                                                                                                                                                         
//	CREATOR:		Helgevold - William Veim                                                                                                                                                                                                                                                              
//                                                                                                                                                                                                                                                                                                                            
//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//  VERSION LOG:                                                                                                                                                                                                                                                                                                   
//	VERSION		DATE				SIGN						DESCRIPTION                                                                                                                                                                                                                                 
//	1.0.0				2023-02-10		William Veim			Initial release                                                                                                                                                                                                                                  
//	2.0.0				2025-03-10		Fredrik Bjerkenes		Rework
//	2.1.0				2026-01-23		William Veim			Bugfix time accumulation
//	2.1.1				2026-03-13		William Veim			Bugfix step in if number running < minimum number
//	2.1.2				2026-03-18		William Veim			Added startup delay and moved number of running to top off program
//	2.2.0				2026-04-13		William Veim			Added input and logic for blocking step logic
//===============================================================================================================================
//
//		DESCRIPTION:
//		Step in/out and alternate actuators on command, based on highest duty/standby time.
//		Based on selection, a new actuator is stepped in if one should be stepped out due to its status going low.
//		
//===============================================================================================================================

(*************************************************************************
 *	INITIALIZING VARIABLE
 *************************************************************************)
 
 Wrk_IndexHighestDutyTime:=		-1;
 Wrk_IndexHighestStandbyTime:=	-1;
 Wrk_HighestDutyTime:=				TIME#0ms;
 Wrk_HighestStandbyTime:=			TIME#0ms;

//Delay after PLC stop or number of ready = 0 
TOF_BlockingDelay(In:=P_First_Run OR Out_NumberOfReady>0, PT:=TIME#10s);

Clear(Out_NumberOfReady);

//COUNTING READY ACTUATORS
FOR Index :=0 TO 15 DO
	
	IF Inp_State[Index] THEN
		Inc(Out_NumberOfReady);
	END_IF;
	
END_FOR;

(*************************************************************************
 *	CHECK FOR ACTUATOR LOSS
 *************************************************************************)
 
FOR Index := 0 TO 15 DO
	
	//Accumulate duty time
	IF Out_Start[Index] THEN
		Wrk_ActuatorTimeStack[Index]:=ADD_TIME(Wrk_ActuatorTimeStack[Index], GetMyTaskInterval());
	//Accumulate standby time
	ELSE
		Wrk_ActuatorTimeStack[Index]:=SUB_TIME(Wrk_ActuatorTimeStack[Index], GetMyTaskInterval());
	END_IF;
	
	//Look for actuator whit higest duty time (Next one to stop)
	IF Wrk_ActuatorTimeStack[Index] > Wrk_HighestDutyTime AND Out_Start[Index] THEN
		Wrk_IndexHighestDutyTime:=		Index;
		Wrk_HighestDutyTime:=				Wrk_ActuatorTimeStack[Index];
	END_IF;
	
	//Look for actuator whit highest standby time (Next one to start)
	IF Wrk_ActuatorTimeStack[Index] < Wrk_HighestStandbyTime AND Inp_State[Index] THEN
		Wrk_IndexHighestStandbyTime:=	Index;
		Wrk_HighestStandbyTime:=			Wrk_ActuatorTimeStack[Index];
	END_IF;
	
	//State not OK - Output high (Stop actuator)
	IF (NOT Inp_State[Index] AND Out_Start[Index] AND NOT Event_Loss) AND NOT TOF_BlockingDelay.Q AND NOT Inp_Block THEN
		
		Wrk_ActuatorTimeStack[Index]:=TIME#0s;
		Out_Start[Index]:=FALSE;
		Event_Loss := TRUE;
		
	END_IF;
END_FOR;

(*************************************************************************
 *	STEP IN NEW ACTUATOR
 *************************************************************************)
 
//Comand step in, alternate OR new on loss AND number running lower than max
Tmp_StepIn := (Cmd_StepIn AND Out_NumberOfReady > Out_NumberOfRunning) 
						OR (Cmd_Alternate AND Out_NumberOfReady > Out_NumberOfRunning) 
						OR (Event_Loss AND Cfg_NewOnLoss) 
						OR (Out_NumberOfRunning < Cfg_MinimumCount  AND Out_NumberOfRunning < Out_NumberOfReady AND Out_NumberOfRunning < Cfg_MaximumCount);

IF Tmp_StepIn AND Wrk_IndexHighestStandbyTime > -1 AND NOT Inp_Block THEN
	
	Out_Start[Wrk_IndexHighestStandbyTime]:=TRUE;
	Wrk_ActuatorTimeStack[Wrk_IndexHighestStandbyTime]:=TIME#0s;
	
END_IF;

(*************************************************************************
 *	STEP OUT ACTUATOR
 *************************************************************************)

//Comand step out or alternate
Tmp_StepOut :=(Cmd_StepOut 
							OR (Cmd_Alternate AND Out_NumberOfReady > Out_NumberOfRunning) 
							OR Out_NumberOfRunning > Cfg_MaximumCount) AND Out_NumberOfRunning > Cfg_MinimumCount ;

IF Tmp_StepOut AND Wrk_IndexHighestDutyTime > -1 AND NOT Inp_Block THEN

	Out_Start[Wrk_IndexHighestDutyTime]:=FALSE;
	Wrk_ActuatorTimeStack[Wrk_IndexHighestDutyTime]:=TIME#0s;

END_IF;

(*************************************************************************
 *	VARIABEL CONTROL
 *************************************************************************)

// Reset command
Cmd_Alternate := FALSE;
Cmd_StepIn := FALSE;
Cmd_StepOut := FALSE;
Event_Loss := FALSE;

//Clear before loop
Clear(Out_NumberOfRunning);

FOR Index :=0 TO 15 DO
	
	//Counting number running
	IF Out_Start[Index] THEN
		Inc(Out_NumberOfRunning);
	END_IF;
	
END_FOR;
